//As a user, I want to read a daily digest post generated by AI that summarizes the top discussions, recorded matches, and standings, allowing me to quickly catch up on recent events
//GET
import { NextResponse } from "next/server";
import type { Prisma } from "@/prisma/generated/index.js";
import { prisma } from "@/prisma/client";
import { withAuth } from "@/utils/auth";
import { Client } from "@gradio/client";
export const dynamic = "force-dynamic";


type DigestData = Awaited<ReturnType<typeof collectDigestData>>;
type StandingsRow = { points?: number; team?: { name?: string } };
type StandingsSection = { table?: StandingsRow[] };
type DigestModelResponse = { data?: unknown };

function isObjectRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function extractTextFromConversationEntry(entry: unknown): string | null {
  if (typeof entry === "string" && entry.trim()) {
    return entry.trim();
  }

  if (Array.isArray(entry)) {
    for (let index = entry.length - 1; index >= 0; index -= 1) {
      const candidate = extractTextFromConversationEntry(entry[index]);
      if (candidate) {
        return candidate;
      }
    }
    return null;
  }

  if (isObjectRecord(entry)) {
    const directFields = ["content", "text", "message", "value"];
    for (const field of directFields) {
      const candidate = entry[field];
      if (typeof candidate === "string" && candidate.trim()) {
        return candidate.trim();
      }
    }
  }

  return null;
}

function collectStringCandidates(value: unknown, bucket: string[]) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed) {
      bucket.push(trimmed);
    }
    return;
  }

  if (Array.isArray(value)) {
    value.forEach((entry) => collectStringCandidates(entry, bucket));
    return;
  }

  if (isObjectRecord(value)) {
    Object.values(value).forEach((entry) => collectStringCandidates(entry, bucket));
  }
}

function extractDigestText(result: DigestModelResponse, prompt: string) {
  if (!Array.isArray(result.data)) {
    throw new Error("Digest generation failed");
  }

  const [conversation, messageText] = result.data;

  if (typeof messageText === "string" && messageText.trim()) {
    return messageText.trim();
  }

  if (Array.isArray(conversation)) {
    for (let index = conversation.length - 1; index >= 0; index -= 1) {
      const candidate = extractTextFromConversationEntry(conversation[index]);
      if (candidate) {
        return candidate;
      }
    }
  }

  const candidates: string[] = [];
  collectStringCandidates(result.data, candidates);

  const normalizedPrompt = prompt.trim();
  const fallback = candidates
    .filter((candidate) => {
      const normalized = candidate.trim();
      if (!normalized) return false;
      if (normalized === normalizedPrompt) return false;
      if (["low", "mid", "high"].includes(normalized.toLowerCase())) return false;
      return normalized.length >= 40;
    })
    .sort((left, right) => right.length - left.length)[0];

  if (fallback) {
    return fallback;
  }

  console.error("Unexpected daily digest response:", JSON.stringify(result.data));

  throw new Error("Digest generation returned an unexpected format");
}

async function collectDigestData() {
  const since = new Date(Date.now() - 24 * 60 * 60 * 1000);

  const topThreads = await prisma.thread.findMany({
    where: {
      createdAt: {
        gte: since,
      },
      status: "VISIBLE",
    },
    include: {
      posts: true,
      tags: {
        include: {
          tag: true,
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
    take: 5,
  });

  const recentMatches = await prisma.match.findMany({
    where: {
      status: "FINISHED",
      utcDate: {
        gte: since,
      },
    },
    include: {
      homeTeam: true,
      awayTeam: true,
    },
    orderBy: {
      utcDate: "desc",
    },
    take: 5,
  });

  const latestStandings = await prisma.standingsSnapshot.findFirst({
    orderBy: {
      fetchedAt: "desc",
    },
  });

  return {
    topThreads,
    recentMatches,
    latestStandings,
  };
}

function buildDigestPrompt({
  topThreads,
  recentMatches,
  latestStandings,
}: DigestData) {
  const threadSummary = topThreads
    .map((t: DigestData["topThreads"][number], i: number) => {
      const tags = t.tags
        .map((x: DigestData["topThreads"][number]["tags"][number]) => x.tag.name)
        .join(", ");
      return `${i + 1}. ${t.title} ${tags ? `[tags: ${tags}]` : ""}`;
    })
    .join("\n");

  const matchSummary = recentMatches
    .map((m: DigestData["recentMatches"][number], i: number) => {
      return `${i + 1}. ${m.homeTeam.name} ${m.scoreHome}-${m.scoreAway} ${m.awayTeam.name}`;
    })
    .join("\n");

  let standingsSummary = "No standings data available.";
  const standingsPayload =
    latestStandings?.data &&
    typeof latestStandings.data === "object" &&
    !Array.isArray(latestStandings.data)
      ? (latestStandings.data as Prisma.JsonObject)
      : null;
  const standingsData = Array.isArray(standingsPayload?.standings)
    ? (standingsPayload.standings as StandingsSection[])
    : [];
  const topTable = Array.isArray(standingsData[0]?.table)
    ? standingsData[0].table
    : [];

  if (topTable.length > 0) {
    standingsSummary = topTable
      .slice(0, 5)
      .map(
        (team: StandingsRow, i: number) =>
          `${i + 1}. ${team.team?.name ?? "Unknown"} - ${team.points ?? 0} pts`
      )
      .join("\n");
  }

  return `
You are generating a daily sports community digest for SportsDeck.
Write a short, engaging digest in English. Only give me the clear summary without any extra sentence.

Include:
1. A summary of the top discussions
2. A summary of recent finished matches
3. A short standings update

Top discussions:
${threadSummary}

Recent matches:
${matchSummary}

Standings:
${standingsSummary}

Write in a concise, readable style for sports fans.
  `.trim();
}

function buildFallbackDigest({
  topThreads,
  recentMatches,
  latestStandings,
}: DigestData) {
  const discussionLines =
    topThreads.length > 0
      ? topThreads.map((thread, index) => {
          const postCount = thread.posts.length;
          const tags = thread.tags
            .map((entry) => entry.tag.name)
            .slice(0, 3)
            .join(", ");

          return `${index + 1}. ${thread.title}${tags ? ` (${tags})` : ""} - ${postCount} post${postCount === 1 ? "" : "s"}`;
        })
      : ["No major new discussions were created in the last 24 hours."];

  const matchLines =
    recentMatches.length > 0
      ? recentMatches.map((match, index) => {
          return `${index + 1}. ${match.homeTeam.name} ${match.scoreHome}-${match.scoreAway} ${match.awayTeam.name}`;
        })
      : ["No completed matches were recorded in the last 24 hours."];

  let standingsLines = ["No standings snapshot is available right now."];
  const standingsPayload =
    latestStandings?.data &&
    typeof latestStandings.data === "object" &&
    !Array.isArray(latestStandings.data)
      ? (latestStandings.data as Prisma.JsonObject)
      : null;
  const standingsData = Array.isArray(standingsPayload?.standings)
    ? (standingsPayload.standings as StandingsSection[])
    : [];
  const topTable = Array.isArray(standingsData[0]?.table)
    ? standingsData[0].table
    : [];

  if (topTable.length > 0) {
    standingsLines = topTable.slice(0, 5).map((team, index) => {
      return `${index + 1}. ${team.team?.name ?? "Unknown"} - ${team.points ?? 0} pts`;
    });
  }

  return [
    "SportsDeck Daily Digest",
    "",
    "Top discussions",
    ...discussionLines,
    "",
    "Recent finished matches",
    ...matchLines,
    "",
    "Standings watch",
    ...standingsLines,
  ].join("\n");
}

async function generateDigestText(prompt: string) {
  const apiKey = process.env.AI_DAILY_DIGEST_API;
  const modelUrl = process.env.AI_DAILY_DIGEST;

  if (!apiKey || !modelUrl) {
    throw new Error("Digest model is not configured");
  }

  const client = await Client.connect(modelUrl);
  const result = (await client.predict(apiKey, [prompt, []])) as DigestModelResponse;

  return extractDigestText(result, prompt);
}

export const POST = withAuth(
  async (_request, payload) => {
    const today = new Date().toISOString().slice(0, 10);

    const existing = await prisma.thread.findFirst({
      where: {
        type: "GENERAL",
        title: `Daily Digest - ${today}`,
      },
      include: {
        posts: true,
      },
    });

    if (existing) {
      return NextResponse.json(existing, { status: 200 });
    }

    const data = await collectDigestData();
    const prompt = buildDigestPrompt(data);
    let digestText: string;

    try {
      digestText = await generateDigestText(prompt);
    } catch (error) {
      console.error("AI daily digest fallback triggered:", error);
      digestText = buildFallbackDigest(data);
    }

    const thread = await prisma.thread.create({
      data: {
        type: "GENERAL",
        title: `Daily Digest - ${today}`,
        posts: {
          create: {
            authorId: payload.userId,
            body: digestText,
          },
        },
      },
      include: {
        posts: true,
      },
    });

    return NextResponse.json(thread, { status: 201 });
  },
  // { requireRole: "ADMIN" }
);
